// @generated by:gauntlet run:godseye-recovery-native-20261111
import { writeFile } from "node:fs/promises";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { pathsDisjoint } from "./recovery-lab-bridge.js";
import { RecoveryLaboratory } from "./recovery-lab-fixture.js";

describe("T-AC-43 signed native physical PostgreSQL recovery", () => {
  let lab: RecoveryLaboratory;
  let fullLabel: string;
  let diffLabel: string;
  let boundary: Awaited<ReturnType<RecoveryLaboratory["markersAndArchive"]>>;
  let target: Awaited<ReturnType<RecoveryLaboratory["start"]>>;

  beforeAll(async () => {
    lab = await RecoveryLaboratory.create();
    await lab.backup("full");
    const first = await lab.info();
    fullLabel = first.backup.find((backup) => backup.type === "full")?.label ?? "";
    await lab.query("INSERT INTO recovery_marker VALUES ('differential-base')");
    await lab.backup("diff");
    const differential = await lab.info();
    diffLabel = differential.backup.find((backup) => backup.type === "diff")?.label ?? "";
    boundary = await lab.markersAndArchive();
    // Keep a second completed full generation; restore still binds the earlier differential chain explicitly.
    await lab.backup("full");
  });
  afterAll(async () => {
    await lab?.cleanup();
    if (lab)
      await writeFile(
        "artifacts/test-results/recovery-lab-observation.json",
        JSON.stringify(
          {
            observedAt: new Date().toISOString(),
            tool: lab.provenance.version,
            qualification: null,
            privateMaterialPublished: false,
            cleanupCompleted: true,
            managedGateChecks: lab.managedGateChecks,
            infoSchema: lab.infoShape,
          },
          null,
          2,
        ),
      );
  });

  it("T-AC-43 authenticates current signed tools and retains two full generations with a dependent differential/WAL chain", async () => {
    const info = await lab.info();

    expect(lab.provenance.version).toBe("pgBackRest 2.60.0");
    expect(lab.provenance.securityGap).toBeNull();
    expect(
      lab.provenance.sources.some(
        (source) => source.signerFingerprint === "B97B0AFCAA1A47F044F244A07FCC7D46ACCC4CF8",
      ),
    ).toBe(true);
    expect(lab.provenance.packages.every((item) => /^[a-f0-9]{64}$/.test(item.sha256))).toBe(true);
    expect(info.name).toBe(lab.policy.stanza);
    expect(info.status.code).toBe(0);
    expect(info.backup.filter((backup) => backup.type === "full")).toHaveLength(2);
    const differential = info.backup.find((backup) => backup.label === diffLabel);
    expect(differential?.prior).toBe(fullLabel);
    expect(differential?.archive.start).toMatch(/^[A-F0-9]{24}$/);
    expect(differential?.archive.stop).toMatch(/^[A-F0-9]{24}$/);
    expect(differential?.lsn.start).toMatch(/^[A-F0-9]+\/[A-F0-9]+$/);
    expect(differential?.lsn.stop).toMatch(/^[A-F0-9]+\/[A-F0-9]+$/);
    expect(
      (
        await lab.query<{ version: string }>("SELECT current_setting('server_version') AS version")
      )[0]?.version,
    ).toMatch(/^18\.6/);
  });

  it("T-AC-43 requires the private ephemeral cipher material to inspect the actual encrypted repository", async () => {
    expect(await lab.rejectsWrongCipher()).toBe(true);
  });

  it("T-AC-43 restores the explicit differential chain to the known transaction boundary in new disjoint data/WAL paths", async () => {
    const restored = await lab.restore("target", diffLabel, boundary.targetTime, boundary.timeline);
    expect(restored.code).toBe(0);
    target = await lab.start("target");

    expect(target.started, target.categories.join(",")).toBe(true);
    expect(pathsDisjoint(lab.policy.binding, target)).toBe(true);
    expect(target.wal).toBe(`${lab.root}/target/wal`);
    const state = await lab.query<{
      recovery: boolean;
      paused: boolean;
      pause_state: string;
      system_id: string;
      read_only: string;
      archive_mode: string;
      archive_command: string;
    }>(
      "SELECT pg_is_in_recovery() AS recovery, pg_is_wal_replay_paused() AS paused, pg_get_wal_replay_pause_state() AS pause_state, system_identifier::text AS system_id, current_setting('transaction_read_only') AS read_only, current_setting('archive_mode') AS archive_mode, current_setting('archive_command') AS archive_command FROM pg_control_system()",
      target,
    );
    expect(state[0]).toMatchObject({
      recovery: true,
      paused: true,
      pause_state: "paused",
      system_id: boundary.systemId,
      read_only: "on",
      archive_mode: "off",
    });
    expect(["", "(disabled)"]).toContain(state[0]?.archive_command);
    const [configuration] = await lab.query<{
      target_time: string;
      target_timeline: string;
      target_action: string;
    }>(
      "SELECT current_setting('recovery_target_time') AS target_time, current_setting('recovery_target_timeline') AS target_timeline, current_setting('recovery_target_action') AS target_action",
      target,
    );
    expect(Date.parse(configuration?.target_time ?? "")).toBe(Date.parse(boundary.targetTime));
    expect(configuration).toMatchObject({
      target_timeline: String(boundary.timeline),
      target_action: "pause",
    });
    expect((await lab.postcondition("target")).targetReached).toBe(true);
    expect(await lab.query("SELECT marker FROM recovery_marker ORDER BY marker", target)).toEqual([
      { marker: "before-target" },
      { marker: "differential-base" },
    ]);
    const [lsn] = await lab.query<{ replay_lsn: string }>(
      "SELECT pg_last_wal_replay_lsn()::text AS replay_lsn",
      target,
    );
    const value = (text: string) => {
      const [high, low] = text.split("/");
      return (BigInt(`0x${high}`) << 32n) + BigInt(`0x${low}`);
    };
    expect(value(lsn?.replay_lsn ?? "0/0")).toBeGreaterThanOrEqual(value(boundary.beforeLsn));
    expect(value(lsn?.replay_lsn ?? "0/0")).toBeLessThan(value(boundary.afterLsn));
    expect(
      await lab.query(
        `SELECT datname FROM pg_database WHERE datname = '${lab.catalog.applicationDatabase}'`,
        target,
      ),
    ).toEqual([{ datname: lab.catalog.applicationDatabase }]);
    expect(lab.managedGateChecks).toBeGreaterThan(0);
  });

  it("T-AC-43 blocks restored application credentials and writes while the original source continues unchanged", async () => {
    await expect(lab.connection(target, true)).rejects.toThrow();
    await expect(
      lab.query("INSERT INTO recovery_marker VALUES ('forbidden-target-write')", target),
    ).rejects.toThrow(/read-only/);
    expect(await lab.query("SELECT marker FROM recovery_marker ORDER BY marker")).toEqual([
      { marker: "after-target" },
      { marker: "before-target" },
      { marker: "differential-base" },
    ]);
    await lab.query("INSERT INTO recovery_marker VALUES ('source-keeps-running')");
    expect(
      (
        await lab.query<{ system_id: string }>(
          "SELECT system_identifier::text AS system_id FROM pg_control_system()",
        )
      )[0]?.system_id,
    ).toBe(boundary.systemId);
    expect(
      await lab.query(
        "SELECT marker FROM recovery_marker WHERE marker = 'source-keeps-running'",
        target,
      ),
    ).toEqual([]);
    expect((await lab.postcondition("target")).sourceRunning).toBe(true);
  });

  it.each(["wrong-repo", "wrong-stanza", "corrupt"] as const)(
    "T-AC-43 rejects actual %s repository evidence without altering the source",
    async (kind) => {
      const policy = await lab.copiedRepository(kind);
      const restored = await lab.restore(
        kind,
        diffLabel,
        boundary.targetTime,
        boundary.timeline,
        policy,
      );

      expect(restored.code).not.toBe(0);
      expect((await lab.postcondition(kind)).sourceRunning).toBe(true);
      expect(
        await lab.query("SELECT marker FROM recovery_marker WHERE marker = 'source-keeps-running'"),
      ).toEqual([{ marker: "source-keeps-running" }]);
    },
  );

  it("T-AC-43 refuses a nonempty destination without overwrite or source mutation", async () => {
    const restored = await lab.restore(
      "nonempty",
      diffLabel,
      boundary.targetTime,
      boundary.timeline,
    );

    expect(restored.code).not.toBe(0);
    expect(await lab.postcondition("nonempty")).toMatchObject({
      guardPreserved: true,
      sourceRunning: true,
    });
  });

  it("T-AC-43 rejects an unrelated physical source identity even with the original socket and stanza", async () => {
    expect(await lab.rejectForeignSource()).toBe(true);
    expect((await lab.postcondition("target")).sourceRunning).toBe(true);
  });

  it("T-AC-43 fails closed when the selected chain has no archived WAL", async () => {
    const policy = await lab.copiedRepository("missing-wal");
    const restored = await lab.restore(
      "missing-wal",
      diffLabel,
      boundary.targetTime,
      boundary.timeline,
      policy,
    );
    if (restored.code === 0) {
      await lab.start("missing-wal");
      expect((await lab.waitFailure("missing-wal")).stopped).toBe(true);
    } else {
      expect(restored.code).not.toBe(0);
    }
    expect((await lab.postcondition("missing-wal")).sourceRunning).toBe(true);
  });

  it("T-AC-43 refuses to promote or accept a target beyond the archived recoverable interval", async () => {
    const impossibleTime = new Date(Date.parse(boundary.targetTime) + 86_400_000).toISOString();
    const restored = await lab.restore("unreachable", diffLabel, impossibleTime, boundary.timeline);
    expect(restored.code).toBe(0);
    await lab.start("unreachable");

    expect(await lab.waitFailure("unreachable")).toEqual({ stopped: true, unreachable: true });
    expect(await lab.postcondition("unreachable")).toMatchObject({
      unreachable: true,
      sourceRunning: true,
    });
  });
});
